INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('be78dfe1-9595-4905-93e5-33850f329ba7', 'Pequeñas promesas cotidianas', 'Promesas simples', 'Prometo guardarte el último pedazo del postre, escucharte aunque ya conozca la historia, recordarte lo hermosa que estás en tus días despeinados y no soltar tu mano en los paseos largos. En esas pequeñeces habita mi devoción.', 'd038b007d7feea8e64b6ae15571c4be73c507f40f7b38a6eaa32cf8e8436fa39', 'LIBRARY', '2026-10-25 19:38:29', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('a4ea31df-3fff-45f2-83e2-a7179dece03d', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo 60b58ae7.', '0e16d1ff78778c39ff9f3d18af8b0a1dabc0b9ea3344dbb4311fe3eb3a092729', 'MANUAL', '2026-10-25 19:39:45', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('fd62f4bb-4843-47e2-933c-87571c6a7e78', 'Promesas de amor', 'Ser tu puerto seguro', 'Te prometo que cuando las tormentas de la rutina o la incertidumbre se acerquen, en mí siempre encontrarás un puerto en calma. No prometo que nunca habrá vientos difíciles, pero sí que jamás tendrás que navegarlos en soledad.', '0131a15cba3b5426658e8f7695fcb93947aa40b085db8965c42272b8f674c5a3', 'LIBRARY', '2026-10-25 19:39:45', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('4d758127-ebc5-403a-a18c-4c39f93c8016', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo e1e00b60.', 'bc940696cc9beff988e0df25fa61f20d5c8fa70f915e810e354b54b2ced912c9', 'MANUAL', '2026-10-25 19:40:00', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('2845e9b9-15a6-4559-9f87-34429e6c2682', 'Ternura y cariño', 'Cuidar de tu paz', 'Hoy le pido a la vida que te trate con la misma delicadeza y amor con la que tú tratas a todo lo que te rodea. Mereces risas sinceras, abrazos largos y la tranquilidad de saber cuánto te adoro en cada instante.', '7d0ecd6f84730bf7447053c44c2e75e2f0e34e0a06b535d19b878c9fbe82ea20', 'LIBRARY', '2026-10-25 19:40:00', '2026-10-25', 'SENT', 1, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('c189867f-e716-4e9d-812e-be552f8ac25d', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo 55237acc.', 'cc9715bd99e25965bbe9185e51f62d3fb0e3ee06b30d153989d2343d6eb72c35', 'MANUAL', '2026-10-25 22:07:02', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('68e7752f-0f4e-4ac4-9a38-2bea3a493574', 'Recuerdos y momentos especiales', 'El primer instante', 'Todavía guardo nítido el recuerdo de la primera vez que conversamos. Había una magia sutil flotando en el aire, una sospecha bendita de que mi vida estaba a punto de cambiar para siempre. Y qué dicha haber acertado.', '2e7f056b4edc86afdf54e6b25414148bf5044a6d9d5d8d0aa6e4d306856ed4a0', 'LIBRARY', '2026-10-25 22:07:02', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('ecba834e-6266-4181-8099-60074b7df0c7', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo 38e3ef4b.', '808373576004d5bd06decd64cc6589318ec8366de2811afb01bb600c1f384c2a', 'MANUAL', '2026-10-25 22:07:33', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('d935d100-7ce3-4626-a1de-9eb1175faf28', 'Mensajes especiales para fechas importantes', 'Celebrando tu existir', 'En este día memorable, quiero renovar todos y cada uno de mis votos de ternura. Gracias por existir, por regalarme tu compañía y por ser la melodía más hermosa que jamás escuché. Te amo con todo mi ser.', '2cf03b315687a0178621c821299cb77e7e7cb5cf61c189a7d8b11bf777682ca0', 'LIBRARY', '2026-10-25 22:07:33', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('c7375bad-9177-4095-92ae-9c320853b70b', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo affb7a16.', '959f8dcddbb060d8b3fb8e95b3ed022dc54ce24e416e390c8cb777a126b3b11d', 'MANUAL', '2026-10-25 22:29:58', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('9c239c46-0dad-4371-8c80-93d5fe88e931', 'Ternura y cariño', 'Detalles que enamoran', 'Amo la forma en que tus ojos brillan cuando algo te emociona, el tono suave con el que me hablas y esa manera tan tuya de llenar de dulzura los pequeños momentos. Eres mi pensamiento más bonito de esta mañana y de todas las que vendrán.', 'c396332400957d4ad846811da4d5a0114af83bd3292ae354e3d0af1b5e9ad8c5', 'LIBRARY', '2026-10-25 22:29:58', '2026-10-25', 'SENT', 2, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('339718e0-44b2-469f-a340-cfc1b7ccdc46', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo 41191747.', '03d1264dffc05bdeea1c293d58906e676a842f454f282ce454e1a36969a33c80', 'MANUAL', '2026-10-25 22:47:00', '2026-10-25', 'SENT', 2, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('8bbcfe6b-71c2-4dd2-8229-4f5013b525bc', 'Ternura y cariño', 'El calor de tus abrazos', 'Si pudiera detener el tiempo en un solo instante, elegiría ese segundo justo en el que me abrazas y el resto del mundo desaparece. En tus brazos no existe el frío, ni la prisa, ni el cansancio. Que hoy sientas todo el calor de mi corazón acompañando cada uno de tus pasos.', 'c3c7c3622eb863195d5af012e245c6765d688b1c4d7047798bc4d6ea64f115b8', 'LIBRARY', '2026-10-25 22:47:00', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('a66f6669-141a-4a52-9e4a-cac1ab13379f', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo 525ebd57.', 'fcb51bcd979f48c9c08a364ff623045f9f4f5d329f3f3633d29057898e6eb026', 'MANUAL', '2026-10-25 22:47:30', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('6a54ccfb-5f3e-4fd1-8538-a6239aa97e1e', 'Promesas de amor', 'Pacto de sinceridad', 'Te prometo verdad en mis palabras, calidez en mis miradas y una lealtad que no conoce fisuras. Eres mi elección incondicional hoy, mañana y hasta donde la vida nos permita soñar.', 'c48b63ea271212a4051dd55d5fb79af57950b1619c04c33a233b8f1352d6d401', 'LIBRARY', '2026-10-25 22:47:30', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('c2893dc5-18ec-4c71-af94-48db3909f82d', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo e60d500d.', 'fd7c4a17903d552f524f360210763974c0e7560c8ee4c770bcaabe6904c3ef2e', 'MANUAL', '2026-10-25 23:00:57', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('8599427a-64d8-44b1-995b-168b5fa4938b', 'Gratitud por tener a esa persona', 'Gratitud serena', 'Hoy doy gracias por todo lo que eres y por todo lo que provocas en mí. Gracias por convertir las dificultades en aprendizajes y las tardes sencillas en recuerdos inolvidables. Eres una bendición diaria.', '1df949c207f3e265a9af96fa29e82bf09a07f849dd83746251bda34ec8fa82f9', 'LIBRARY', '2026-10-25 23:00:57', '2026-10-25', 'SENT', 1, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('fa710960-6e9f-45a7-9f5a-e11513e61204', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo 2e740a82.', '9ca80dbad3bdcf3802fb9b36a12526e82c59fb3aa2b77ac652e7020bdb9ce248', 'MANUAL', '2026-10-25 23:03:41', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('e9c8f0bb-2d41-41b9-badb-a5961143b69a', 'Mensajes especiales para fechas importantes', 'Un hito de amor', 'Hoy es un día especial para detener el reloj y mirar con ternura todo el camino recorrido. Cada paso, cada risa y cada lágrima compartida han hecho más sólida esta unión sagrada. Brindo por nosotros y por todo lo hermoso que aún nos espera.', 'a5463f6ec06ee9a6145767b0a36b8fcd91e761a6abfb0b109a717283ac9b39fd', 'LIBRARY', '2026-10-25 23:03:41', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('b4b299ea-78bc-40e9-84b5-543c08a41a94', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo 6d7c074d.', '37229f2b22f81cd3caf908c22a427a1fe530a263a075585324df4305e6ae32c1', 'MANUAL', '2026-10-25 23:03:56', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('ada28c8d-02d2-4822-aba3-9c276207c916', 'Promesas de amor', 'Crecer a tu lado', 'Prometo aprender contigo, celebrar tus victorias como mías y tenderte la mano antes de que la pidas. Prometo que nuestro amor no será una rutina, sino un jardín que regaremos con paciencia, ilusión y respeto todos los días.', '2963c090ab00ec8ffca2b7d715be8fd2656c5f18297e56d0227c5d490bbd0c4c', 'LIBRARY', '2026-10-25 23:03:56', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('0676dddb-1742-4b60-a425-74826706febf', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo 986589a6.', '2c8cfcea6f7d1c371c840fd406373a9ff9dbd1fa99ec8f6f71c8fd09ce2e8a5c', 'MANUAL', '2026-10-25 23:07:04', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('ce4e4108-ef3a-41f2-87fe-6d426162f59b', 'Amor profundo', 'Raíces en el alma', 'Amarte se ha convertido en la certeza más dulce y serena de mi existencia. No es un impulso pasajero ni una emoción que el viento pueda disipar; es un arraigo hondo, como el de los árboles centenarios que encuentran en la tierra su única razón de ser. Gracias por ser el refugio donde mi corazón descansa.', '268b7d40249a152873c6149562973eb52aa8d7d8b3039655917918e57ba7d501', 'LIBRARY', '2026-10-25 23:07:04', '2026-10-25', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('c5e0c416-f91e-43be-acac-d3342116b6b7', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo 3d84781f.', 'ce1cab00fcce81538228026553c8878d615bd01f8de294949da7a0e72695476c', 'MANUAL', '2026-10-26 03:19:09', '2026-10-26', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('6f053130-bb49-4561-b625-7d8f261ec6cd', 'Mensajes poéticos', 'El secreto del viento', 'Le pedí al viento del alba que rozara tus mejillas con suavidad de pétalo, llevándote en su brisa el eco de mi suspiro más sincero: te amo con la delicadeza del rocío y la constancia de las olas del mar.', '6b890b491a4c33945ca0a8ca1c05c359a2b85fb76dbbfeea831c718e5eccba2f', 'LIBRARY', '2026-10-26 03:19:09', '2026-10-26', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('baa6a6c3-c10f-46b5-85c1-bd8cc6849bd8', 'Amor profundo', 'Prueba 1', 'Eres la persona más maravillosa del universo 82ad061e.', '7a34e89928bc342d9994a46c79ab059c8f8d8d7456de530a4d15e28acb4c2a5f', 'MANUAL', '2026-10-26 03:37:09', '2026-10-26', 'SENT', 0, NULL);
INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('fdc0db05-e8a9-4bd2-884d-80f3f12044ab', 'Apoyo en los días difíciles', 'Tu refugio incondicional', 'Cuando sientas cansancio, no dudes en apoyarte en mí. No hay error que pueda disminuir lo que vales, ni problema que juntos no podamos resolver paso a paso. Recuerda que mi amor te acompaña en cada segundo.', 'fbb165ead291c943274bd063fbae981ba05ee01c2ff86163093bbd95e43d5ca0', 'LIBRARY', '2026-10-26 03:37:09', '2026-10-26', 'SENT', 0, NULL);
