INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('97f97167-f2f9-4595-bca5-26227f7fe0eb', 'Amor profundo', 'La gravedad de nosotros', 'Así como los planetas giran en armonía alrededor del sol sin cuestionar su órbita, mi mundo entero encontró su centro el día que entraste en él. Eres la fuerza que equilibra mis dudas y multiplica mis alegrías. Mi amor por ti es eterno y absoluto.', 'bdd3d1017c83197b87eac9066ea9ef6dc985be80f0378df61a36cf05d1ab51b2', 'LIBRARY', '2026-10-26 18:18:24', '2026-10-26', 'SENT', 0, NULL);
