INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('4a61cc55-51b2-490f-834c-5ab57ccc3524', 'Apoyo en los días difíciles', 'Estoy aquí para ti', 'Si hoy sientes que el día pesa un poco más de lo habitual, recuerda que no tienes que ser fuerte todo el tiempo. Respira hondo. Estoy aquí para sostener tu mano, para escuchar tu silencio o para recordarte lo inmensamente capaz que eres.', '1c3f956107f82221b0fa35efd0cf11a21d188df2fb5d8670a0c867f3fa6c48f7', 'LIBRARY', '2026-10-26 18:32:56', '2026-10-26', 'SENT', 0, NULL);
