INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('0fe4fbf1-87bd-4a88-9c60-75e8340c715f', 'Pequeñas promesas cotidianas', 'La ternura de lo simple', 'Prometo darte siempre un beso de buenos días, celebrar tus pequeños triunfos cotidianos y buscar tu mirada en las habitaciones llenas de gente para recordarte con un guiño que solo existes tú para mí.', 'c9067efd3707061e1377d7c5f297fe2f6b30687e59610549074ade5de878f6eb', 'LIBRARY', '2026-10-26 18:33:58', '2026-10-26', 'SENT', 0, NULL);
