INSERT OR REPLACE INTO letters (id, category, title, content, normalized_hash, source, created_at, scheduled_for, status, attempt_count, last_error) VALUES ('185fb106-5578-4600-a2c2-ebf8fd7dda3d', 'Gratitud por tener a esa persona', 'Gracias por coincidir', 'En un universo con miles de millones de almas y posibilidades infinitas, haber coincidido contigo en este punto exacto del tiempo es el milagro más hermoso de mi vida. Gracias por elegirme cada día, tanto como yo te elijo a ti.', 'd1b8a5c3b28d10ffc93a815ee1a47217f1427db50153da64abb85f8d97d1c5cf', 'LIBRARY', '2026-10-26 18:35:34', '2026-10-26', 'SCHEDULED', 0, NULL);
